INSERT INTO public.jobs (id, title, description, department, "position", "companyId", status, "expirationDate", "createdBy", "createdAt", "updatedBy", "updatedAt") VALUES
	('cmljevpp706xt0jmn3aaqf5uf', 'Customer Brand Officer', '<h1>Job Details</h1><h2>This is a  test document</h2><p></p>', 'Illo illum optio error voluptate consequuntur nulla ipsam eligendi.', 'Neque itaque fugiat quod.', 'master-company', 'ACTIVE', '2026-08-06 00:00:00', 'cmk14l4dv000018lunc4af9lb', '2026-02-12 12:04:50.779', 'cmk14l4dv000018lunc4af9lb', '2026-02-12 12:04:50.779'),
	('cmljrutql06xv0jmn2gk5xo5r', 'Software Engineer', '<h3>🧩 About the Role</h3><p>We are seeking a skilled and motivated <strong>Software Engineer</strong> to join our growing engineering team. You will be responsible for designing, developing, and maintaining scalable web applications that support our internal operations and customer-facing platforms.</p><p>You will collaborate closely with product managers, designers, and other engineers to deliver high-quality software solutions that are secure, reliable, and performant.</p><hr><h3>🚀 Key Responsibilities</h3><ul><li><p>Design, develop, test, and maintain scalable web applications</p></li><li><p>Write clean, maintainable, and well-documented code</p></li><li><p>Participate in code reviews and technical discussions</p></li><li><p>Optimize application performance and improve system scalability</p></li><li><p>Troubleshoot and resolve software defects and production issues</p></li><li><p>Contribute to system architecture decisions and technical improvements</p></li><li><p>Work closely with cross-functional teams to deliver product features</p></li></ul><hr><h3>🛠 Required Skills &amp; Qualifications</h3><ul><li><p>Bachelor’s degree in Computer Science, Engineering, or related field</p></li><li><p>3+ years of experience in software development</p></li><li><p>Strong proficiency in JavaScript / TypeScript</p></li><li><p>Experience with React or similar frontend frameworks</p></li><li><p>Backend experience with Node.js, Java (Spring Boot), or similar</p></li><li><p>Familiarity with RESTful APIs and database systems (PostgreSQL, MySQL)</p></li><li><p>Understanding of Git version control and CI/CD pipelines</p></li></ul><hr><h3>⭐ Preferred Qualifications</h3><ul><li><p>Experience with cloud platforms (AWS, Azure, or GCP)</p></li><li><p>Knowledge of Docker and containerized environments</p></li><li><p>Familiarity with Agile/Scrum methodologies</p></li><li><p>Experience working with HR or enterprise management systems</p></li></ul><hr><h3>💼 What We Offer</h3><ul><li><p>Competitive salary and performance bonuses</p></li><li><p>Flexible hybrid work environment</p></li><li><p>Health insurance and wellness benefits</p></li><li><p>Professional development support</p></li><li><p>Opportunity to work on impactful, large-scale systems</p></li></ul><p></p>', 'Engineering', 'Lead Developer', 'cmkmqsya900010jp6pgd1bb3l', 'ACTIVE', '2026-03-14 00:00:00', 'cmk14l4dv000018lunc4af9lb', '2026-02-12 18:08:04.365', 'cmk14l4dv000018lunc4af9lb', '2026-02-12 18:08:04.365'),
	('cmljrwa2z06xw0jmnhd83vkwu', 'Customer Operations Director', '<h3>🧩 About the Role</h3><p>We are seeking a skilled and motivated <strong>Software Engineer</strong> to join our growing engineering team. You will be responsible for designing, developing, and maintaining scalable web applications that support our internal operations and customer-facing platforms.</p><p>You will collaborate closely with product managers, designers, and other engineers to deliver high-quality software solutions that are secure, reliable, and performant.</p><hr><h3>🚀 Key Responsibilities</h3><ul><li><p>Design, develop, test, and maintain scalable web applications</p></li><li><p>Write clean, maintainable, and well-documented code</p></li><li><p>Participate in code reviews and technical discussions</p></li><li><p>Optimize application performance and improve system scalability</p></li><li><p>Troubleshoot and resolve software defects and production issues</p></li><li><p>Contribute to system architecture decisions and technical improvements</p></li><li><p>Work closely with cross-functional teams to deliver product features</p></li></ul><hr><h3>🛠 Required Skills &amp; Qualifications</h3><ul><li><p>Bachelor’s degree in Computer Science, Engineering, or related field</p></li><li><p>3+ years of experience in software development</p></li><li><p>Strong proficiency in JavaScript / TypeScript</p></li><li><p>Experience with React or similar frontend frameworks</p></li><li><p>Backend experience with Node.js, Java (Spring Boot), or similar</p></li><li><p>Familiarity with RESTful APIs and database systems (PostgreSQL, MySQL)</p></li><li><p>Understanding of Git version control and CI/CD pipelines</p></li></ul><hr><h3>⭐ Preferred Qualifications</h3><ul><li><p>Experience with cloud platforms (AWS, Azure, or GCP)</p></li><li><p>Knowledge of Docker and containerized environments</p></li><li><p>Familiarity with Agile/Scrum methodologies</p></li><li><p>Experience working with HR or enterprise management systems</p></li></ul><hr><h3>💼 What We Offer</h3><ul><li><p>Competitive salary and performance bonuses</p></li><li><p>Flexible hybrid work environment</p></li><li><p>Health insurance and wellness benefits</p></li><li><p>Professional development support</p></li><li><p>Opportunity to work on impactful, large-scale systems</p></li></ul><p></p>', 'Vitae ea temporibus distinctio quasi soluta quae inventore natus repellat.', 'Voluptas itaque distinctio iste culpa magnam ipsa.', 'master-company', 'ACTIVE', '2026-11-28 00:00:00', 'cmk14l4dv000018lunc4af9lb', '2026-02-12 18:09:12.203', 'cmk14l4dv000018lunc4af9lb', '2026-02-12 18:09:12.203'),
	('cmljrzxm406xx0jmn2kiv0fzc', 'Regional Paradigm Consultant', '<h3>🧩 About the Role</h3><p>We are seeking a skilled and motivated <strong>Software Engineer</strong> to join our growing engineering team. You will be responsible for designing, developing, and maintaining scalable web applications that support our internal operations and customer-facing platforms.</p><p>You will collaborate closely with product managers, designers, and other engineers to deliver high-quality software solutions that are secure, reliable, and performant.</p><hr><h3>🚀 Key Responsibilities</h3><ul><li><p>Design, develop, test, and maintain scalable web applications</p></li><li><p>Write clean, maintainable, and well-documented code</p></li><li><p>Participate in code reviews and technical discussions</p></li><li><p>Optimize application performance and improve system scalability</p></li><li><p>Troubleshoot and resolve software defects and production issues</p></li><li><p>Contribute to system architecture decisions and technical improvements</p></li><li><p>Work closely with cross-functional teams to deliver product features</p></li></ul><hr><h3>🛠 Required Skills &amp; Qualifications</h3><ul><li><p>Bachelor’s degree in Computer Science, Engineering, or related field</p></li><li><p>3+ years of experience in software development</p></li><li><p>Strong proficiency in JavaScript / TypeScript</p></li><li><p>Experience with React or similar frontend frameworks</p></li><li><p>Backend experience with Node.js, Java (Spring Boot), or similar</p></li><li><p>Familiarity with RESTful APIs and database systems (PostgreSQL, MySQL)</p></li><li><p>Understanding of Git version control and CI/CD pipelines</p></li></ul><hr><h3>⭐ Preferred Qualifications</h3><ul><li><p>Experience with cloud platforms (AWS, Azure, or GCP)</p></li><li><p>Knowledge of Docker and containerized environments</p></li><li><p>Familiarity with Agile/Scrum methodologies</p></li><li><p>Experience working with HR or enterprise management systems</p></li></ul><hr><h3>💼 What We Offer</h3><ul><li><p>Competitive salary and performance bonuses</p></li><li><p>Flexible hybrid work environment</p></li><li><p>Health insurance and wellness benefits</p></li><li><p>Professional development support</p></li><li><p>Opportunity to work on impactful, large-scale systems</p></li></ul><p></p>', 'Sunt accusantium ducimus omnis.', 'Esse magni debitis consectetur illum tempore corrupti quis.', 'cmkmr43ny00030jp65etc04zw', 'ACTIVE', '2025-12-17 00:00:00', 'cmk14l4dv000018lunc4af9lb', '2026-02-12 18:12:02.668', 'cmk14l4dv000018lunc4af9lb', '2026-02-12 18:12:02.668'),
	('cmlmci83c06xy0jmnf05h499q', 'Software Engineer', '<h1>Software Engineer</h1><p><strong>Location:</strong> Lagos, Nigeria (Hybrid)<br><strong>Department:</strong> Engineering<br><strong>Employment Type:</strong> Full-Time</p><hr><h3>🧩 About the Role</h3><p>We are seeking a skilled and motivated <strong>Software Engineer</strong> to join our growing engineering team. You will be responsible for designing, developing, and maintaining scalable web applications that support our internal operations and customer-facing platforms.</p><p>You will collaborate closely with product managers, designers, and other engineers to deliver high-quality software solutions that are secure, reliable, and performant.</p><hr><h3>🚀 Key Responsibilities</h3><ul><li><p>Design, develop, test, and maintain scalable web applications</p></li><li><p>Write clean, maintainable, and well-documented code</p></li><li><p>Participate in code reviews and technical discussions</p></li><li><p>Optimize application performance and improve system scalability</p></li><li><p>Troubleshoot and resolve software defects and production issues</p></li><li><p>Contribute to system architecture decisions and technical improvements</p></li><li><p>Work closely with cross-functional teams to deliver product features</p></li></ul><hr><h3>🛠 Required Skills &amp; Qualifications</h3><ul><li><p>Bachelor’s degree in Computer Science, Engineering, or related field</p></li><li><p>3+ years of experience in software development</p></li><li><p>Strong proficiency in JavaScript / TypeScript</p></li><li><p>Experience with React or similar frontend frameworks</p></li><li><p>Backend experience with Node.js, Java (Spring Boot), or similar</p></li><li><p>Familiarity with RESTful APIs and database systems (PostgreSQL, MySQL)</p></li><li><p>Understanding of Git version control and CI/CD pipelines</p></li></ul><hr><h3>⭐ Preferred Qualifications</h3><ul><li><p>Experience with cloud platforms (AWS, Azure, or GCP)</p></li><li><p>Knowledge of Docker and containerized environments</p></li><li><p>Familiarity with Agile/Scrum methodologies</p></li><li><p>Experience working with HR or enterprise management systems</p></li></ul><hr><h3>💼 What We Offer</h3><ul><li><p>Competitive salary and performance bonuses</p></li><li><p>Flexible hybrid work environment</p></li><li><p>Health insurance and wellness benefits</p></li><li><p>Professional development support</p></li><li><p>Opportunity to work on impactful, large-scale systems</p></li></ul><hr><h3>📩 How to Apply</h3><p>Interested candidates should submit their resume and portfolio to <a target="_blank" rel="noopener noreferrer nofollow" href="mailto:careers@company.com"><strong>careers@company.com</strong></a> with the subject line <em>“Software Engineer Application”</em>.</p>', 'Ex labore dignissimos saepe ullam asperiores architecto.', 'Sed fuga ab modi inventore ipsa labore nihil qui unde.', 'master-company', 'ACTIVE', '2025-03-16 00:00:00', 'cmk14l4dv000018lunc4af9lb', '2026-02-14 13:21:40.728', 'cmk14l4dv000018lunc4af9lb', '2026-02-14 13:21:40.728');
